// Auto-registers the geo (geojson-feature-collection) handler and the UTM
// derive provider with @alizarin/napi on import. The native binding (index.js)
// is generated by `napi build` and exposes `geoHandlerPtr()` and
// `utmDeriveProviderPtr()` — BigInt pointers to their C-ABI infos, which
// registration.js hands to the host (the NAPI analogue of Python's
// `import alizarin_geo`).
//
//   const alizarin = require('@alizarin/napi');
//   require('@alizarin/geo-napi'); // registers both
//
const { binding, register } = require('./registration.js')

register(require('@alizarin/napi'))

module.exports = binding
